import styled from '@emotion/styled';
import { Paragraph } from 'components/UI';
import { theme } from 'theme';

export const StyledDrillDownTableChartSwapper = styled.div({
  '.ag-header-cell': {
    background: '#0000000a !important',
  },
  '.ag-cell': {
    borderTop: 'none !important',
    borderBottom: 'none !important',
  },
  '.ag-row:not(.ag-row-even) .ag-cell': {
    background: '#fbfbf9 !important',
  },
  '.ag-row-first .ag-cell': {
    background: '#e0f3ff !important',
  },
});

export const StyledRefreshDate = styled(Paragraph)({
  fontSize: 12,
  color: theme.colors.charts.txt.status.comparison.neutral,
  fontWeight: 400,
  margin: 0,
});
